create function pg_temp.sign(s jsonb) returns jsonb language sql as $$ select s||jsonb_build_object('snapshot_checksum',atlas_legacy.master_snapshot_hash(s-'snapshot_checksum')) $$;
select is(atlas_legacy.preview_master_data_snapshot(pg_temp.sign(jsonb_set(jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"wrong-dish-type-code"'),'{records,dish_types,0,dish_type_code}','"stir_fry"')))->>'success','false','approved source Dish Type ID cannot be rebound to another catalogue code');
select is(
  atlas_legacy.preview_master_data_snapshot(
    pg_temp.sign(
      jsonb_set(
        jsonb_set(
          jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"duplicate-name-different-type"'),
          '{records,dish_types}',
          pg_temp.recipe_fixture()#>'{records,dish_types}' || jsonb_build_array(jsonb_build_object('legacy_id','2','dish_type_code','savory','source_name','Món mặn'))
        ),
        '{records,dishes}',
        pg_temp.recipe_fixture()#>'{records,dishes}' || jsonb_build_array(jsonb_build_object('legacy_id','101','dish_code','v1-dish-101','dish_name','Canh mẫu','dish_type_legacy_id','2','dish_status','ACTIVE'))
      )
    )
  )->>'success',
  'true',
  'same active Dish display name in different Dish Types is a valid separate identity'
);
select is(
  atlas_legacy.preview_master_data_snapshot(
    pg_temp.sign(
      jsonb_set(
        jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"duplicate-name-same-type"'),
        '{records,dishes}',
        pg_temp.recipe_fixture()#>'{records,dishes}' || jsonb_build_array(jsonb_build_object('legacy_id','102','dish_code','v1-dish-102','dish_name','Canh mẫu','dish_type_legacy_id','1','dish_status','ACTIVE'))
      )
    )
  )->>'success',
  'false',
  'same active Dish display name within one Dish Type remains ambiguous and blocked'
);
insert into atlas_core.actors(actor_id,actor_type,display_name) values ('aa920000-0000-4000-8000-000000000001','HUMAN','Synthetic Recipe importer');
create temp table evidence(label text primary key,snapshot jsonb,preview jsonb,result jsonb);
insert into evidence values ('a',pg_temp.recipe_fixture(),atlas_legacy.preview_master_data_snapshot(pg_temp.recipe_fixture()),null);
select is((select preview->>'success' from evidence where label='a'),'true','full typed Recipe snapshot is supported');
update evidence set result=atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001') where label='a';
select is((select result->>'success' from evidence where label='a'),'true','full master snapshot applies atomically');
select is((select count(*) from atlas_admin.dishes),1::bigint,'one Dish root');
select is((select count(*) from atlas_admin.recipes),2::bigint,'two typed Recipe roots');
select is((select count(*) from atlas_admin.recipes where school_type_id is null),0::bigint,'legacy GENERAL flag does not create general roots');
select is((select count(*) from atlas_admin.recipe_versions where recipe_version_status='RELEASED_FOR_PLANNING'),2::bigint,'initial Recipes are planning eligible');
select is((select count(*) from atlas_admin.recipe_versions where recipe_version_status='LOCKED'),0::bigint,'legacy is_locked is not copied');
select is((select count(*) from atlas_admin.recipe_line_revisions),3::bigint,'all exact BOM lines materialized');
select ok((select bool_and(basis_portions=100 and created_by_actor_id='aa920000-0000-4000-8000-000000000001'::uuid and validated_by_actor_id=created_by_actor_id and released_by_actor_id=created_by_actor_id and source_evidence->>'source_kind'='OPS_V1_MASTER_SNAPSHOT') from atlas_admin.recipe_versions),'actual import Actor and migration evidence retained');
create temp table prior_versions as select * from atlas_admin.recipe_versions;
create temp table prior_lines as select * from atlas_admin.recipe_line_revisions;
create temp table recipe_ids as select * from atlas_admin.recipes;
insert into evidence(label,snapshot) select 'b',pg_temp.sign(jsonb_set(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-recipe-b"'),'{records,recipes,0,source_record_id}','"999200"'),'{records,recipe_lines,0,source_record_id}','"999300"')) from evidence where label='a';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='b';
select is((select preview->>'success' from evidence where label='b'),'true','source physical row-ID churn is accepted');
select ok((select not exists(select 1 from jsonb_array_elements(preview->'actions') a where a->>'object_type' in ('RECIPE_VERSION','RECIPE_LINE_REVISION') and a->>'action'='CREATE') from evidence where label='b'),'physical IDs alone generate no successor');
update evidence set result=atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001') where label='b';
select is((select result->>'success' from evidence where label='b'),'true','row-ID-only refresh applies');
select is((select count(*) from atlas_admin.recipe_versions),2::bigint,'row-ID churn creates no duplicate versions');
select is((select count(*) from atlas_admin.recipe_line_revisions),3::bigint,'row-ID churn creates no duplicate revisions');
-- Change one quantity; remove Ingredient 2; add Ingredient 3 in the first Recipe.
insert into evidence(label,snapshot)
select 'c',pg_temp.sign(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-recipe-c"'),'{records,recipe_lines}',
 (select jsonb_agg(case when x.value->>'recipe_legacy_id'='dish:100:school-type:1' then jsonb_set(x.value,'{quantity_per_basis}','"2.5"') else x.value end order by x.n) from jsonb_array_elements(snapshot#>'{records,recipe_lines}') with ordinality x(value,n) where x.value->>'legacy_id'<>'recipe:dish:100:school-type:1:ingredient:2') ||
 jsonb_build_array(jsonb_build_object('legacy_id','recipe:dish:100:school-type:1:ingredient:3','source_record_id','800','recipe_legacy_id','dish:100:school-type:1','ingredient_legacy_id','3','unit_legacy_id','Hũ','quantity_per_basis','1','operational_note','New ingredient')))) from evidence where label='b';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='c';
select is((select preview->>'success' from evidence where label='c'),'true','legitimate pre-use composition correction previews');
update evidence set result=atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001') where label='c';
select is((select result->>'success' from evidence where label='c'),'true','composition correction applies');
select is((select count(*) from atlas_admin.recipe_versions),3::bigint,'one changed Recipe creates exactly one successor');
select is((select count(*) from atlas_admin.recipes),2::bigint,'Recipe roots are unchanged');
select is((select count(*) from prior_lines old join atlas_admin.recipe_line_revisions new using(recipe_line_revision_id) where to_jsonb(old) is distinct from to_jsonb(new)),0::bigint,'previous immutable composition is byte-equivalent');
select is((select count(*) from atlas_admin.recipe_versions where recipe_version_status='LOCKED'),1::bigint,'released predecessor locks when successor releases');
select is((select count(*) from atlas_admin.recipe_line_revisions where line_disposition='REMOVED' and predecessor_recipe_line_revision_id is not null and quantity_per_basis=0),1::bigint,'removed membership has an explicit zero REMOVED revision');
select is((select sum(rr.quantity_per_basis) from atlas_admin.recipe_line_revisions rr join atlas_admin.recipe_versions rv using(recipe_version_id) join atlas_admin.ingredients i using(ingredient_id) where rv.recipe_version_status='RELEASED_FOR_PLANNING' and i.ingredient_code='v1-ingredient-1'),4.0::numeric,'exact corrected quantities read back');
select is((select count(*) from atlas_planning.weekly_menus),0::bigint,'master import creates no Weekly Menu');
select is((select count(*) from atlas_planning.need_generation_runs),0::bigint,'master import creates no Need Generation');
-- A different invalid snapshot blocks before any extra master root writes.
insert into evidence(label,snapshot) select 'bad',pg_temp.sign(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-invalid-bom"'),'{records,recipe_lines,0,quantity_per_basis}','"0"')) from evidence where label='c';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='bad';
select is((select preview->>'success' from evidence where label='bad'),'false','database rejects invalid quantity independently of source diagnostics');
select is((select count(*) from atlas_legacy.import_batches where source_system='OPS_V1'),3::bigint,'rejected preview creates no evidence batch');
-- Carry an existing removal through another correction, then reintroduce it.
insert into evidence(label,snapshot) select 'd',pg_temp.sign(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-recipe-d"'),'{records,recipe_lines,0,quantity_per_basis}','"2.75"')) from evidence where label='c';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='d';
update evidence set result=atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001') where label='d';
select is((select result->>'success' from evidence where label='d'),'true','a later correction carries removed line evidence');
insert into evidence(label,snapshot) select 'e',pg_temp.sign(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-recipe-e"'),'{records,recipe_lines}',snapshot#>'{records,recipe_lines}'||jsonb_build_array(jsonb_build_object('legacy_id','recipe:dish:100:school-type:1:ingredient:2','source_record_id','9400','recipe_legacy_id','dish:100:school-type:1','ingredient_legacy_id','2','unit_legacy_id','kg','quantity_per_basis','0.75','operational_note','Reintroduced')))) from evidence where label='d';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='e';
update evidence set result=atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001') where label='e';
select is((select result->>'success' from evidence where label='e'),'true','reintroduction retains exact immediate predecessor');
select is((select count(distinct recipe_line_id) from atlas_admin.recipe_line_revisions where ingredient_id=(select ingredient_id from atlas_admin.ingredients where ingredient_code='v1-ingredient-2')),1::bigint,'reintroduced Ingredient retains one stable Recipe line');
select is((select count(*) from prior_lines old join atlas_admin.recipe_line_revisions new using(recipe_line_revision_id) where to_jsonb(old) is distinct from to_jsonb(new)),0::bigint,'multiple corrections never rewrite old line revisions');
select is(atlas_legacy.preview_master_data_snapshot(pg_temp.sign(jsonb_set(jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"empty-test"'),'{records,recipe_lines}','[]')))->>'success','false','empty BOM blocks even without source diagnostics');
select is(atlas_legacy.preview_master_data_snapshot(pg_temp.sign(jsonb_set(jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"duplicate-test"'),'{records,recipe_lines}',pg_temp.recipe_fixture()#>'{records,recipe_lines}'||jsonb_build_array(pg_temp.recipe_fixture()#>'{records,recipe_lines,0}'))))->>'success','false','duplicate composition key blocks');
select is(atlas_legacy.preview_master_data_snapshot(pg_temp.sign(jsonb_set(jsonb_set(pg_temp.recipe_fixture(),'{snapshot_id}','"unknown-unit"'),'{records,recipe_lines,0,unit_legacy_id}','"123"')))->>'success','false','unknown Unit blocks independently');

