insert into atlas_planning.weekly_menu_approval_snapshot_lines(weekly_menu_approval_snapshot_line_id,weekly_menu_approval_snapshot_id,weekly_menu_id,weekly_menu_version,weekly_menu_line_id,school_id,service_date,menu_slot_code,dish_id)
select 'aa920000-0000-4000-8000-000000000221','aa920000-0000-4000-8000-000000000220',weekly_menu_id,1,weekly_menu_line_id,school_id,service_date,menu_slot_code,dish_id from atlas_planning.weekly_menu_lines;
update atlas_planning.weekly_menus set weekly_menu_status='APPROVED',latest_approved_by_actor_id='aa920000-0000-4000-8000-000000000001',latest_approved_at=transaction_timestamp(),latest_approval_snapshot_id='aa920000-0000-4000-8000-000000000220' where weekly_menu_id='aa920000-0000-4000-8000-000000000200';
set constraints all immediate;
set constraints all deferred;
insert into evidence(label,snapshot) select 'locked',pg_temp.sign(jsonb_set(jsonb_set(snapshot,'{snapshot_id}','"synthetic-post-commit"'),'{records,recipe_lines,0,quantity_per_basis}','"3"')) from evidence where label='e';
update evidence set preview=atlas_legacy.preview_master_data_snapshot(snapshot) where label='locked';
select is((select preview->>'success' from evidence where label='locked'),'false','approved Menu use blocks later base migration');
select ok((select exists(select 1 from jsonb_array_elements(preview->'issues') i where i->>'code'='RECIPE_COMMITTED_USE') from evidence where label='locked'),'blocker uses actual approved Dish-use authority');
select is((select atlas_legacy.apply_master_data_snapshot(snapshot,preview->>'plan_checksum','aa920000-0000-4000-8000-000000000001')->>'success' from evidence where label='locked'),'false','committed-use apply refuses');
select is((select count(*) from atlas_admin.recipe_versions),5::bigint,'no successor after commitment');
select * from finish();
rollback;
